async def migrate(self, migration, *, module: str = 'test', ff=False):
        async with self.con.transaction():
            mig = f"""
                START MIGRATION TO {{
                    module {module} {{
                        {migration}
                    }}
                }};
            """
            if ff:
                await self.con.execute(mig)
                await self.fast_forward_describe_migration()
            else:
                await self.con.execute(f"""
                    {mig}
                    POPULATE MIGRATION;
                    COMMIT MIGRATION;
                """)
